import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import {afterAll, describe, expect, it} from 'vitest';
import transform, {meta} from '../validate-data-token-ownership.mjs';
import {codemodOutcome} from '../../../outcome.mjs';
import {upgrade} from '../../../../../api/upgrade/upgrade.mjs';

const SLOW = 30_000;
const tempRoots = [];

afterAll(() => {
  for (const root of tempRoots) fs.rmSync(root, {recursive: true, force: true});
});

const STALE_THEME = `/* @generated by \`astryx theme build\` */
@layer astryx-base {
  :root { --color-data-categorical-green: #008000; }
}`;

const RAW_USES = {
  'src/chart.tsx': `export const fill = 'var(--color-data-categorical-green)';
export const border = \`1px solid var(--color-data-blue-3)\`;
`,
  'src/chart.css': '.bar { fill: var(--color-data-categorical-green); }\n',
};

/**
 * A project with Core 0.7.0 installed and the given files, as a repository.
 * @param {Record<string, string | object>} files
 */
function project(files) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astryx-data-token-'));
  tempRoots.push(root);
  fs.mkdirSync(path.join(root, '.git'));
  const all = {
    'node_modules/@astryxdesign/core/package.json': {
      name: '@astryxdesign/core',
      version: '0.7.0',
    },
    ...files,
  };
  for (const [rel, contents] of Object.entries(all)) {
    const file = path.join(root, rel);
    fs.mkdirSync(path.dirname(file), {recursive: true});
    fs.writeFileSync(
      file,
      typeof contents === 'string' ? contents : JSON.stringify(contents),
    );
  }
  return root;
}

const PREBUILT = {
  'package.json': {dependencies: {'@astryxdesign/core': '0.7.3'}},
  'src/main.tsx': "import '@astryxdesign/core/astryx.css';\n",
};
const SOURCE_BUILT = {
  'package.json': {
    dependencies: {'@astryxdesign/core': '0.7.3'},
    devDependencies: {'@astryxdesign/build': '0.7.3'},
  },
  'vite.config.ts':
    "import {astryxStylex} from '@astryxdesign/build/vite';\nexport default {plugins: [...astryxStylex()]};\n",
};

const runUpgrade = root =>
  upgrade(
    {from: '0.6.9', codemod: 'validate-data-token-ownership', apply: true},
    {cwd: root},
  );

describe('validate-data-token-ownership', () => {
  it('reads only stylesheets', () => {
    expect(meta.fileExtensions).toEqual(['.css']);
  });

  it('reports stale generated theme CSS with root data defaults as a regeneration', () => {
    expect(() => transform({source: STALE_THEME, path: 'theme.css'})).toThrow(
      /Rebuild it with `astryx theme build`/,
    );
    let thrown;
    try {
      transform({source: STALE_THEME, path: 'theme.css'});
    } catch (err) {
      thrown = err;
    }
    expect(codemodOutcome(thrown)).toMatchObject({
      kind: 'regenerate',
      commands: ['astryx theme build'],
    });
  });

  it('passes raw data-token uses with or without a fallback', () => {
    for (const source of [
      '.bar { fill: var(--color-data-categorical-green); }',
      '.bar { fill: var(--color-data-categorical-green, #008000); }',
      `/* @generated by \`astryx theme build\` */
.bar { fill: var(--color-data-blue-3); }`,
    ]) {
      expect(transform({source, path: 'chart.css'})).toBeUndefined();
    }
  });

  it('does not claim ownership of hand-authored CSS or sparse theme overrides', () => {
    expect(
      transform({
        source: ':root { --color-data-categorical-green: #008000; }',
        path: 'app.css',
      }),
    ).toBeUndefined();
    expect(
      transform({
        source: `/* @generated by \`astryx theme build\` */
@scope ([data-astryx-theme="ocean"]) {
  :scope { --color-data-categorical-green: #008000; }
}`,
        path: 'theme.css',
      }),
    ).toBeUndefined();
  });

  it(
    'completes `astryx upgrade --apply` over raw uses in a prebuilt project',
    async () => {
      const root = project({...PREBUILT, ...RAW_USES});
      const res = await runUpgrade(root);
      expect(res.data.complete).toBe(true);
      expect(res.data.errors ?? []).toEqual([]);
      expect(res.data.modifiedFiles ?? []).toEqual([]);
    },
    SLOW,
  );

  it(
    'completes `astryx upgrade --apply` over raw uses in a source-built project',
    async () => {
      const root = project({...SOURCE_BUILT, ...RAW_USES});
      const res = await runUpgrade(root);
      expect(res.data.complete).toBe(true);
      expect(res.data.errors ?? []).toEqual([]);
      expect(res.data.modifiedFiles ?? []).toEqual([]);
    },
    SLOW,
  );

  it(
    'leaves `astryx upgrade --apply` incomplete on stale generated theme CSS, naming the rebuild',
    async () => {
      const root = project({...PREBUILT, 'src/theme.css': STALE_THEME});
      const res = await runUpgrade(root);
      expect(res.data).toMatchObject({
        complete: false,
        errorCode: 'ERR_CODEMOD_PROTECTED',
        errors: [],
        regenerate: [
          expect.objectContaining({
            file: 'src/theme.css',
            commands: ['astryx theme build'],
          }),
        ],
      });
    },
    SLOW,
  );
});
